#!/usr/bin/env python3
"""Turn an fdroid scanner report into scandelete rules, using the build graph
of chrome_public_apk to tell which flagged files the build actually reads.

Usage: scan_rules.py <findings.tsv> <build-inputs.txt> <output dir>

<build-inputs.txt> is the output of `ninja -C out/Default -t inputs
chrome_public_apk`, with paths relative to the out dir.

Writes:
  scan-rules.txt       scandelete paths (fdroidserver metadata syntax), with
                       a comment per rule
  build-graph.md       summary, and the flagged files the build reads, which
                       need a decision by hand
  findings-build.tsv   findings.tsv plus an in_build column
"""

import collections
import glob
import os
import sys

# Categories handled by their own issues; never delete them with these rules.
KEEP_CATEGORIES = {'toolchain', 'java', 'nonfree'}


def human(n):
    for unit in ('B', 'KB', 'MB', 'GB'):
        if n < 1024 or unit == 'GB':
            return f'{n:.0f} {unit}' if unit == 'B' else f'{n:.1f} {unit}'
        n /= 1024


def load_inputs(path):
    inputs = set()
    with open(path) as f:
        for line in f:
            p = line.strip()
            if p.startswith('../../'):
                inputs.add(os.path.normpath(p[len('../../'):]))
    return inputs


def ancestors(path):
    parts = path.split('/')
    return ['/'.join(parts[:i]) for i in range(1, len(parts))]


def min_depth(path):
    return 3 if path.startswith('third_party/') else 2


def main():
    findings, inputs_file, out = sys.argv[1:4]
    os.makedirs(out, exist_ok=True)
    inputs = load_inputs(inputs_file)

    rows = []
    with open(findings) as f:
        next(f)
        for line in f:
            cat, kind, path, size = line.rstrip('\n').split('\t')
            rows.append((cat, kind, path, int(size), path in inputs))

    # A rule may not cover any flagged file that the build reads or that
    # belongs to a category tracked elsewhere.
    blocked_dirs = set()
    for cat, kind, path, size, in_build in rows:
        if in_build or cat in KEEP_CATEGORIES:
            blocked_dirs.update(ancestors(path))
            blocked_dirs.add(path)

    rules = collections.defaultdict(lambda: [0, 0, collections.Counter()])
    for cat, kind, path, size, in_build in rows:
        if in_build or cat in KEEP_CATEGORIES:
            continue
        dirs = ancestors(path)
        chosen = path
        for d in dirs[min_depth(path) - 1 :]:
            if d not in blocked_dirs:
                chosen = d
                break
        r = rules[chosen]
        r[0] += 1
        r[1] += size
        r[2][kind] += 1

    # Drop rules nested inside another rule.
    names = sorted(rules)
    merged = {}
    for name in names:
        parent = next((a for a in ancestors(name) if a in merged), None)
        if parent:
            m = merged[parent]
            m[0] += rules[name][0]
            m[1] += rules[name][1]
            m[2].update(rules[name][2])
        else:
            merged[name] = rules[name]

    with open(os.path.join(out, 'scan-rules.txt'), 'w') as f:
        f.write(
            '# scandelete rules generated by scan_rules.py: flagged files that\n'
            '# chrome_public_apk does not read (not in `ninja -t inputs`).\n'
            '# fdroidserver deletes only the flagged files under each path.\n'
        )
        for name, (n, size, kinds) in sorted(merged.items()):
            k = ', '.join(f'{x} {c}' for x, c in kinds.most_common(2))
            f.write(f'{glob.escape(name)}  # {n} files, {human(size)}: {k}\n')

    with open(os.path.join(out, 'findings-build.tsv'), 'w') as f:
        f.write('category\tkind\tpath\tbytes\tin_build\n')
        for cat, kind, path, size, in_build in rows:
            f.write(f'{cat}\t{kind}\t{path}\t{size}\t{"yes" if in_build else "no"}\n')

    stats = collections.defaultdict(lambda: [0, 0, 0, 0])
    review = collections.defaultdict(lambda: [0, 0, collections.Counter()])
    for cat, kind, path, size, in_build in rows:
        s = stats[cat]
        if in_build:
            s[0] += 1
            s[1] += size
            if cat not in KEEP_CATEGORIES:
                parts = path.split('/')
                g = '/'.join(parts[: min(min_depth(path), len(parts) - 1)]) or '(top level)'
                review[g][0] += 1
                review[g][1] += size
                review[g][2][kind] += 1
        else:
            s[2] += 1
            s[3] += size

    lines = [
        '## Flagged files and the chrome_public_apk build graph',
        '',
        f'{len(merged)} scandelete rules cover '
        f'{sum(r[0] for r in merged.values())} flagged files that the build does not read.',
        '',
        '| category | read by build | size | not read | size |',
        '|---|---:|---:|---:|---:|',
    ]
    for cat in ('test', 'other', 'toolchain', 'java', 'nonfree'):
        s = stats[cat]
        lines.append(f'| {cat} | {s[0]} | {human(s[1])} | {s[2]} | {human(s[3])} |')
    lines += [
        '',
        '### Test/other files the build reads (need a decision)',
        '',
        '| directory | count | size | kinds |',
        '|---|---:|---:|---|',
    ]
    for name, (n, size, kinds) in sorted(review.items(), key=lambda kv: -kv[1][0]):
        k = ', '.join(f'{x} {c}' for x, c in kinds.most_common(3)).replace('|', '\\|')
        lines.append(f'| `{name}` | {n} | {human(size)} | {k} |')
    text = '\n'.join(lines) + '\n'
    with open(os.path.join(out, 'build-graph.md'), 'w') as f:
        f.write(text)
    print(text)
    step = os.environ.get('GITHUB_STEP_SUMMARY')
    if step:
        with open(step, 'a') as f:
            f.write(text)


if __name__ == '__main__':
    main()
